1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
can: gs_usb: gs_usb_receive_bulk_callback(): fix URB memory
 leak

In gs_can_open(), the URBs for USB-in transfers are allocated, added to the
parent->rx_submitted anchor and submitted. In the complete callback
gs_usb_receive_bulk_callback(), the URB is processed and resubmitted. In
gs_can_close() the URBs are freed by calling
usb_kill_anchored_urbs(parent->rx_submitted).

However, this does not take into account that the USB framework unanchors
the URB before the complete function is called. This means that once an
in-URB has been completed, it is no longer anchored and is ultimately not
released in gs_can_close().

Fix the memory leak by anchoring the URB in the
gs_usb_receive_bulk_callback() to the parent->rx_submitted anchor.

Fixes: d08e973a77d1 ("can: gs_usb: Added support for the GS_USB CAN devices")
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20260105-gs_usb-fix-memory-leak-v2-1-cc6ed6438034@pengutronix.de
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
The USB core unanchors URBs before invoking the completion callback. In `gs_usb_receive_bulk_callback()`, the URB is resubmitted but not re-anchored to `parent->rx_submitted`. As a result, when `gs_can_close()` calls `usb_kill_anchored_urbs()`, URBs that have completed are no longer anchored and are not killed or freed, leading to a memory leak.

Here is the patch:

 static void gs_usb_receive_bulk_callback(struct urb *urb)
 {
 	struct gs_usb *parent = urb->context;
 	struct gs_can *dev;
 	struct net_device *netdev;
 	int rc;
 	struct net_device_stats *stats;
 	struct gs_host_frame *hf = urb->transfer_buffer;
 	unsigned int minimum_length, data_length;
 	struct gs_tx_context *txc;
 	struct can_frame *cf;
 	struct canfd_frame *cfd;
 	struct sk_buff *skb;

 	BUG_ON(!parent);

 	switch (urb->status) {
 	case 0: /* success */
 		break;
 	case -ENOENT:
 	case -ESHUTDOWN:
 		return;
 	default:
 		/* do not resubmit aborted urbs. eg: when device goes down */
 		return;
 	}

 	minimum_length = sizeof(hf->header);
 	if (urb->actual_length < minimum_length) {
 		dev_err_ratelimited(&parent->udev->dev,
 				    "short read (actual_length=%u, minimum_length=%u)\n",
 				    urb->actual_length, minimum_length);

 		goto resubmit_urb;
 	}

 	/* device reports out of range channel id */
 	if (hf->channel >= parent->channel_cnt)
 		goto device_detach;

 	dev = parent->canch[hf->channel];

 	netdev = dev->netdev;
 	stats = &netdev->stats;

 	if (!netif_device_present(netdev))
 		return;

 	if (!netif_running(netdev))
 		goto resubmit_urb;

 	minimum_length = gs_usb_get_minimum_rx_length(dev, hf, &data_length);
 	if (urb->actual_length < minimum_length) {
 		stats->rx_errors++;
 		stats->rx_length_errors++;

 		if (net_ratelimit())
 			netdev_err(netdev,
 				   "short read (actual_length=%u, minimum_length=%u)\n",
 				   urb->actual_length, minimum_length);

 		goto resubmit_urb;
 	}

 	if (hf->echo_id == GS_HOST_FRAME_ECHO_ID_RX) { /* normal rx */
 		if (hf->flags & GS_CAN_FLAG_FD) {
 			skb = alloc_canfd_skb(netdev, &cfd);
 			if (!skb)
 				return;

 			cfd->can_id = le32_to_cpu(hf->can_id);
 			cfd->len = data_length;
 			if (hf->flags & GS_CAN_FLAG_BRS)
 				cfd->flags |= CANFD_BRS;
 			if (hf->flags & GS_CAN_FLAG_ESI)
 				cfd->flags |= CANFD_ESI;

 			memcpy(cfd->data, hf->canfd->data, data_length);
 		} else {
 			skb = alloc_can_skb(netdev, &cf);
 			if (!skb)
 				return;

 			cf->can_id = le32_to_cpu(hf->can_id);
 			can_frame_set_cc_len(cf, hf->can_dlc, dev->can.ctrlmode);

 			memcpy(cf->data, hf->classic_can->data, data_length);

 			/* ERROR frames tell us information about the controller */
 			if (le32_to_cpu(hf->can_id) & CAN_ERR_FLAG)
 				gs_update_state(dev, cf);
 		}

 		gs_usb_rx_offload(dev, skb, hf);
 	} else { /* echo_id == hf->echo_id */
 		if (hf->echo_id >= GS_MAX_TX_URBS) {
 			netdev_err(netdev,
 				   "Unexpected out of range echo id %u\n",
 				   hf->echo_id);
 			goto resubmit_urb;
 		}

 		txc = gs_get_tx_context(dev, hf->echo_id);

 		/* bad devices send bad echo_ids. */
 		if (!txc) {
 			netdev_err(netdev,
 				   "Unexpected unused echo id %u\n",
 				   hf->echo_id);
 			goto resubmit_urb;
 		}

 		skb = dev->can.echo_skb[hf->echo_id];
 		stats->tx_packets++;
 		stats->tx_bytes += gs_usb_get_echo_skb(dev, skb, hf);
 		gs_free_tx_context(txc);

 		atomic_dec(&dev->active_tx_urbs);

 		netif_wake_queue(netdev);
 	}

 	if (hf->flags & GS_CAN_FLAG_OVERFLOW) {
 		stats->rx_over_errors++;
 		stats->rx_errors++;

 		skb = alloc_can_err_skb(netdev, &cf);
 		if (!skb)
 			goto resubmit_urb;

 		cf->can_id |= CAN_ERR_CRTL;
 		cf->len = CAN_ERR_DLC;
 		cf->data[1] = CAN_ERR_CRTL_RX_OVERFLOW;

 		gs_usb_rx_offload(dev, skb, hf);
 	}

 	can_rx_offload_irq_finish(&dev->offload);

 resubmit_urb:
 	usb_fill_bulk_urb(urb, parent->udev,
 			  parent->pipe_in,
 			  hf, parent->hf_size_rx,
 			  gs_usb_receive_bulk_callback, parent);

+	usb_anchor_urb(urb, &parent->rx_submitted);
+
 	rc = usb_submit_urb(urb, GFP_ATOMIC);

 	/* USB failure take down all interfaces */
 	if (rc == -ENODEV) {
 device_detach:
 		for (rc = 0; rc < parent->channel_cnt; rc++) {
 			if (parent->canch[rc])
 				netif_device_detach(parent->canch[rc]->netdev);
 		}
 	}
 }



